// The lexer generated by jison strips newlines from the template before
// rendering the position of a parse error. For multi-line templates this
// collapses the template onto a single line, so the `-----^` marker no longer
// points at the offending character (see #2023). This replacement keeps the
// template's line breaks and places the marker directly below the error.

const CONTEXT_LENGTH = 20;

function showPosition() {
  const past = this.matched.substr(0, this.matched.length - this.match.length);
  const pre =
    (past.length > CONTEXT_LENGTH ? '...' : '') + past.substr(-CONTEXT_LENGTH);

  let upcoming = this.match;
  if (upcoming.length < CONTEXT_LENGTH) {
    upcoming += this._input.substr(0, CONTEXT_LENGTH - upcoming.length);
  }
  upcoming =
    upcoming.substr(0, CONTEXT_LENGTH) +
    (upcoming.length > CONTEXT_LENGTH ? '...' : '');

  const lines = (pre + upcoming).split('\n');
  const errorLine = pre.split('\n').length - 1;
  const errorColumn = pre.length - pre.lastIndexOf('\n') - 1;

  let position = '';
  for (let i = 0; i < lines.length; i++) {
    position += lines[i] + '\n';
    if (i === errorLine) {
      position += '-'.repeat(errorColumn) + '^\n';
    }
  }

  return position.slice(0, -1);
}

export default function installErrorPosition(parser) {
  parser.lexer.showPosition = showPosition;
}
